import { existsSync } from 'fs';
import { join } from 'path';

export function validateProjectPackageJson(
  projectPackageJson: Record<string, unknown>,
  sourceProject: string,
  sourceProjectRoot: string,
  projectPackageJsonPath: string
): ProjectFilesViolation[] {
  const violations: ProjectFilesViolation[] = [];

  if (projectPackageJson.private === true) {
    return violations;
  }

  const createViolation = (message: string): ProjectFilesViolation => ({
    file: projectPackageJsonPath,
    message,
    sourceProject,
  });

  const name = projectPackageJson.name;
  if (typeof name !== 'string') {
    violations.push(
      createViolation('The project package.json should have a "name" field')
    );
  } else if (name.startsWith('@') && !name.startsWith('@nx/')) {
    violations.push(
      createViolation('The package name should be scoped to the @nx org')
    );
  }

  const publishConfig = projectPackageJson.publishConfig as
    | { access?: unknown }
    | undefined;
  if (!publishConfig || publishConfig.access !== 'public') {
    violations.push(
      createViolation(
        'Public packages should have "publishConfig": { "access": "public" } set in their package.json'
      )
    );
  }

  if (
    existsSync(join(sourceProjectRoot, 'executors.json')) &&
    projectPackageJson.executors !== './executors.json'
  ) {
    violations.push(
      createViolation(
        'The project has an executors.json, but does not reference "./executors.json" in the "executors" field of its package.json'
      )
    );
  }

  if (
    existsSync(join(sourceProjectRoot, 'generators.json')) &&
    projectPackageJson.generators !== './generators.json'
  ) {
    violations.push(
      createViolation(
        'The project has an generators.json, but does not reference "./generators.json" in the "generators" field of its package.json'
      )
    );
  }

  const exports = projectPackageJson.exports;
  if (
    typeof exports !== 'object' ||
    exports === null ||
    Array.isArray(exports) ||
    Object.keys(exports).length === 0
  ) {
    violations.push(
      createViolation(
        'The project package.json should have an "exports" object specified'
      )
    );
  }

  return violations;
}
